import { db } from "../lib/db";
import { pve, node, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
import { writeFile, unlink } from "node:fs/promises";
import { ovhConfigured } from "../lib/ovh";
import { allocateDedicatedIp, releaseDedicatedIp, syncDedicatedIpPool } from "../lib/dedicated-ip";
import { allocateIp, allocateSshPort, gatewayIp } from "../lib/ipam";
import { syncPortForwards } from "./network";
import { billingSweep } from "./billing";
import { randomBytes } from "node:crypto";
import type { Job, Server } from "@prisma/client";

const POLL_MS = 3000;
const MAX_ATTEMPTS = 3;

function generatePassword(): string {
  // URL-safe, no ambiguous chars, 16 chars
  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
}

async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
  const server = await db.server.findUnique({
    where: { id: job.serverId! },
    include: { plan: true, osTemplate: true, node: true },
  });
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  return server as any;
}

/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
async function nodeFor(server: any) {
  const n =
    server.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    // No Node rows yet — use the env-configured primary via the global client.
    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
  }
  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
}

/** YAML-safe indent of a multi-line script under a `content: |` block. */
function indentBlock(text: string, spaces: number): string {
  const pad = " ".repeat(spaces);
  return text.split("\n").map((l) => pad + l).join("\n");
}

/**
 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
 * plus any control-panel/app install script and selected add-ons. Long installs
 * run in the background so the VM reports ready promptly.
 */
function buildCloudInit(server: any): string {
  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
  const setup: string[] = [];
  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
  if (addons.malwareScanner)
    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);

  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
  return `#cloud-config
package_update: true
packages:
  - qemu-guest-agent
ssh_pwauth: true
disable_root: false
write_files:
  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
    permissions: "0644"
    content: |
      PermitRootLogin yes
      PasswordAuthentication yes
  - path: /root/nxeon-setup.sh
    permissions: "0755"
    content: |
${indentBlock(script, 6)}
runcmd:
  - systemctl enable --now qemu-guest-agent
  - systemctl restart ssh || systemctl restart sshd
  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
`;
}

const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";

async function provision(job: Job) {
  const server = await loadServer(job);
  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });

  const { conn, row: nodeRow } = await nodeFor(server);
  const storage = server.plan.storageTier === "hdd"
    ? nodeRow?.storageHdd ?? "vmdata-hdd"
    : nodeRow?.storageNvme ?? "vmdata";

  const vmid = server.vmid ?? (await conn.nextVmid());
  const password = generatePassword();

  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
  if (server.wantsDedicatedIp && ovhConfigured()) {
    try {
      dedicated = await allocateDedicatedIp(server.id, vmid);
    } catch (e) {
      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
    }
  }
  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp()));
  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort()));

  await db.server.update({
    where: { id: server.id },
    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
  });

  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
    newid: vmid,
    name: server.hostname,
    full: 1,
    storage,
  });
  await conn.waitForTask(cloneUpid, 600_000);

  // Per-server cloud-init snippet (base + panel/app install + add-ons)
  const snippet = buildCloudInit(server);
  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
    console.error("[worker] snippet write failed", e)
  );

  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
  const sshkeys = keys.length
    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
    : undefined;
  const cfg: Record<string, any> = {
    cores: server.plan.cpuCores,
    memory: server.plan.ramMB,
    ciuser: "root",
    cipassword: password,
    sshkeys,
    nameserver: "1.1.1.1 8.8.8.8",
    onboot: 1,
    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
  };
  if (dedicated) {
    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
  } else {
    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp()}`;
  }
  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);

  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
    disk: "scsi0",
    size: `${server.plan.diskGB}G`,
  });

  if (!dedicated) await syncPortForwards();

  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  await conn.waitForTask(startUpid);

  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  const isImage = server.osTemplate.category !== "PLAIN_OS";
  const sshLine = dedicated
    ? `ssh root@${dedicated.address}`
    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
  await notify(
    server.userId,
    `Server ${server.hostname} is ready`,
    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
    `/dashboard/servers/${server.id}`
  );
}

async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
  const server = await loadServer(job);
  const { conn } = await nodeFor(server);
  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
  await conn.waitForTask(upid);
  await db.server.update({
    where: { id: server.id },
    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
  });
}

async function destroyVm(conn: any, vmid: number) {
  // Stop first (ignore failure if already stopped), then destroy
  try {
    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(stopUpid);
  } catch {
    /* already stopped or does not exist */
  }
  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
    "destroy-unreferenced-disks": 1,
    purge: 1,
  });
  await conn.waitForTask(delUpid, 600_000);
}

async function remove(job: Job) {
  const server = await loadServer(job);
  const { conn } = await nodeFor(server);
  if (server.vmid) {
    try {
      await destroyVm(conn, server.vmid);
    } catch (e: any) {
      // VM may never have been created; only swallow "does not exist"
      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
    }
    // Best-effort: remove the per-server cloud-init snippet
    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
  }
  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC)
  await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
  await db.server.delete({ where: { id: server.id } });
  await syncPortForwards();
}

async function reinstall(job: Job) {
  const server = await loadServer(job);
  const { conn } = await nodeFor(server);
  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
  if (server.vmid) await destroyVm(conn, server.vmid);
  await provision(job);
}

async function suspend(job: Job, unsuspend: boolean) {
  const server = await loadServer(job);
  const { conn } = await nodeFor(server);
  if (unsuspend) {
    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
    await syncPortForwards();
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
    await conn.waitForTask(upid);
    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  } else {
    try {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
      await conn.waitForTask(upid);
    } catch { /* may already be stopped */ }
    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
    await syncPortForwards();
  }
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[worker] notify failed", e);
  }
}

async function resize(job: Job) {
  const server = await loadServer(job);
  const payload = (job.payload ?? {}) as { planId?: string };
  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
  if (!newPlan) throw new Error("resize: target plan not found");
  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");

  const { conn } = await nodeFor(server);
  const wasRunning = server.status === "RUNNING";
  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
    cores: newPlan.cpuCores,
    memory: newPlan.ramMB,
  });
  if (newPlan.diskGB > server.plan.diskGB) {
    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
      disk: "scsi0",
      size: `${newPlan.diskGB}G`,
    });
  }
  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
  // CPU/RAM changes need a power cycle to apply
  if (wasRunning) {
    try {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
      await conn.waitForTask(stopUpid, 120_000);
    } catch {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
      await conn.waitForTask(stopUpid);
    }
    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
    await conn.waitForTask(startUpid);
  }
  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
    `/dashboard/servers/${server.id}`);
}

async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
  const server = await loadServer(job);
  const payload = (job.payload ?? {}) as { name?: string };
  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
  if (!name) throw new Error("snapshot: invalid name");
  const { conn } = await nodeFor(server);
  let upid: string;
  if (op === "create") {
    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
  } else if (op === "delete") {
    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
  } else {
    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
  }
  await conn.waitForTask(upid, 600_000);
  if (op === "rollback") {
    // rollback leaves the VM stopped; bring it back if the server should be running
    const current = await db.server.findUnique({ where: { id: server.id } });
    if (current?.status === "RUNNING") {
      try {
        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
        await conn.waitForTask(startUpid);
      } catch { /* may already be running */ }
    }
  }
}

async function passwordReset(job: Job) {
  const server = await loadServer(job);
  if (!server.vmid) throw new Error("password reset: server has no VM yet");
  const { conn } = await nodeFor(server);
  const password = generatePassword();

  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
  let applied = false;
  try {
    const upid = await conn.post(
      `/nodes/${conn.node}/qemu/${server.vmid}/agent/set-user-password`,
      { username: "root", password }
    );
    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
    applied = true;
  } catch (e) {
    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
  }

  // Fallback: rewrite cloud-init password and reboot so it reapplies.
  if (!applied) {
    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
    if (server.status === "RUNNING") {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
      await conn.waitForTask(upid);
    }
  }

  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
  await notify(
    server.userId,
    `Root password reset for ${server.hostname}`,
    "Your new root password is available on the server's Overview tab.",
    `/dashboard/servers/${server.id}`
  );
}

async function backupCreate(job: Job) {
  const server = await loadServer(job);
  const { conn } = await nodeFor(server);
  const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
    vmid: server.vmid,
    storage: "backup",
    mode: "snapshot",
    compress: "zstd",
  });
  await conn.waitForTask(upid, 3_600_000);
  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
    `/dashboard/servers/${server.id}`);
}

const handlers: Record<string, (job: Job) => Promise<void>> = {
  PROVISION: provision,
  START: (j) => powerAction(j, "start"),
  STOP: (j) => powerAction(j, "stop"),
  REBOOT: (j) => powerAction(j, "reboot"),
  DELETE: remove,
  REINSTALL: reinstall,
  SUSPEND: (j) => suspend(j, false),
  UNSUSPEND: (j) => suspend(j, true),
  RESIZE: resize,
  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
  BACKUP_CREATE: backupCreate,
  PASSWORD_RESET: passwordReset,
  SYNC_FORWARDS: async () => syncPortForwards(),
};

async function runJob(job: Job) {
  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
  await db.job.update({
    where: { id: job.id },
    data: { status: "RUNNING", attempts: { increment: 1 } },
  });
  try {
    await handlers[job.type](job);
    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
    console.log(`[worker] job ${job.id} DONE`);
  } catch (e: any) {
    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
    console.error(`[worker] job ${job.id} FAILED: ${error}`);
    const current = await db.job.findUnique({ where: { id: job.id } });
    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error },
    });
    if (!retriable && job.serverId) {
      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
      if (stillExists) {
        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
      }
    }
  }
}

/**
 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
 * killed worker leaves a job RUNNING forever, which permanently blocks the
 * server's "one in-flight job" guard and strands it in a transitional state.
 */
async function reapStuckJobs() {
  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
  for (const job of stuck) {
    const retriable = job.attempts < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
    });
    if (!retriable && job.serverId) {
      const s = await db.server.findUnique({ where: { id: job.serverId } });
      if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
      }
    }
    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
  }
}

async function main() {
  console.log("[worker] Nxeon provisioning worker starting");
  await reapStuckJobs();
  await syncPortForwards();
  console.log("[worker] port forwards synced");

  let lastSweep = 0;
  let lastIpSync = 0;
  for (;;) {
    if (Date.now() - lastSweep > 10 * 60_000) {
      lastSweep = Date.now();
      try {
        await billingSweep();
      } catch (e) {
        console.error("[billing] sweep error", e);
      }
    }
    // Pull newly-delivered OVH IPs into the pool every 5 min
    if (ovhConfigured() && Date.now() - lastIpSync > 5 * 60_000) {
      lastIpSync = Date.now();
      try {
        const r = await syncDedicatedIpPool();
        if (r.imported > 0) console.log(`[worker] dedicated IP pool: imported ${r.imported}, total ${r.total}`);
      } catch (e) {
        console.error("[worker] IP pool sync error", e);
      }
    }
    try {
      const job = await db.job.findFirst({
        where: { status: "QUEUED" },
        orderBy: { createdAt: "asc" },
      });
      if (job) {
        await runJob(job);
      } else {
        await new Promise((r) => setTimeout(r, POLL_MS));
      }
    } catch (e) {
      console.error("[worker] loop error", e);
      await new Promise((r) => setTimeout(r, POLL_MS));
    }
  }
}

main();

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { vpsTermPriceCents, addMonths } from "./billing-terms";
import { debitWallet, InsufficientBalanceError } from "./wallet";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function queueJob(
  serverId: string,
  type:
    | "SNAPSHOT_CREATE"
    | "SNAPSHOT_DELETE"
    | "SNAPSHOT_ROLLBACK"
    | "BACKUP_CREATE"
    | "RESIZE"
    | "PASSWORD_RESET",
  payload?: Record<string, unknown>
): Promise<{ error?: string }> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };
  await db.job.create({ data: { type, serverId, payload: payload as any } });
  return {};
}

// ---------- Snapshots ----------

export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${name}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${name}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

// ---------- Backups ----------

export async function createBackup(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "BACKUP_CREATE");
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

// ---------- Resize ----------

export async function resizeServer(serverId: string, planId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const newPlan = await db.plan.findUnique({ where: { id: planId } });
  if (!newPlan?.active) return { error: "Plan not available." };
  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
  if (newPlan.diskGB < server.plan.diskGB) {
    return { error: "Disk storage can only grow — choose a plan with equal or larger disk." };
  }
  if (newPlan.priceCents < server.plan.priceCents) {
    return { error: "Downgrades aren't self-service yet — please contact support." };
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };

  // Prorate the upgrade: charge the price difference for the unused portion of the
  // current billing term so mid-term upgrades aren't free (paid servers only).
  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    const now = Date.now();
    const periodStart = addMonths(server.expiresAt, -server.termMonths).getTime();
    const periodMs = server.expiresAt.getTime() - periodStart;
    const remainingFraction = periodMs > 0 ? Math.max(0, Math.min(1, (server.expiresAt.getTime() - now) / periodMs)) : 0;
    const deltaFullTerm =
      vpsTermPriceCents(newPlan.priceCents, server.termMonths) - vpsTermPriceCents(server.plan.priceCents, server.termMonths);
    prorateCents = Math.round(deltaFullTerm * remainingFraction);
    if (prorateCents > 0 && user.balanceCents < prorateCents) {
      return {
        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term. Top up your wallet first.`,
      };
    }
  }

  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };

  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: { userId: server.userId, amountCents: -prorateCents, description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}` },
        });
      }
      await tx.job.create({ data: { type: "RESIZE", serverId, payload: { planId } as any } });
      await tx.auditLog.create({
        data: { userId: user.id, action: "server.resize", detail: `${serverId} -> ${newPlan.slug} prorate=${prorateCents}` },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- Root password reset ----------

export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reset its password." };
  }
  const res = await queueJob(serverId, "PASSWORD_RESET");
  if (!res.error) {
    await db.auditLog.create({
      data: { userId: user.id, action: "server.password_reset", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    revalidatePath(`/admin/servers/${serverId}`);
  }
  return res;
}

// ---------- Port forwarding (firewall/networking) ----------

import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
const MAX_FORWARDS_PER_SERVER = 10;

export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user, server } = await ownedServer(serverId);
  const parsed = z
    .object({
      guestPort: z.coerce.number().int().min(1).max(65535),
      protocol: z.enum(["tcp", "udp"]),
    })
    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
  if (!parsed.success) return { error: "Invalid port." };

  const count = await db.portForward.count({ where: { serverId } });
  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };

  const used = new Set([
    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
  ]);
  let publicPort = 0;
  for (let p = PF_MIN; p <= PF_MAX; p++) {
    if (!used.has(p)) { publicPort = p; break; }
  }
  if (!publicPort) return { error: "No public ports available." };

  await db.portForward.create({
    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
  });
  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function deletePortForward(serverId: string, forwardId: string) {
  const { user } = await ownedServer(serverId);
  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * In-browser VNC console.
 *
 * Fetches a single-use, encrypted ticket from /api/console/[serverId], then
 * connects the browser to the standalone relay websocket (scripts/console-proxy.mjs)
 * using the vendored noVNC RFB client (public/novnc/core/rfb.js).
 *
 * The Proxmox token and raw VNC ticket are NEVER seen here — the ticket handed
 * to us is an opaque encrypted blob that only the relay can decrypt.
 */

type Phase = "idle" | "loading" | "connecting" | "connected" | "error" | "unavailable";

// Hide the import from the bundler so it stays a genuine runtime browser import
// of the static ESM asset under /public/novnc — Turbopack/Webpack must not try
// to resolve or bundle it.
const importESM: (u: string) => Promise<any> =
  typeof window !== "undefined"
    ? (new Function("u", "return import(u)") as (u: string) => Promise<any>)
    : async () => ({});

const RFB_URL = "/novnc/core/rfb.js";

export function Console({ serverId }: { serverId: string }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const rfbRef = useRef<any>(null);
  const [phase, setPhase] = useState<Phase>("idle");
  const [message, setMessage] = useState<string | null>(null);

  const cleanup = useCallback(() => {
    if (rfbRef.current) {
      try {
        rfbRef.current.disconnect();
      } catch {
        /* ignore */
      }
      rfbRef.current = null;
    }
  }, []);

  useEffect(() => () => cleanup(), [cleanup]);

  const connect = useCallback(async () => {
    setMessage(null);
    setPhase("loading");
    cleanup();

    // 1. Make sure the vendored noVNC assets are actually present.
    try {
      const head = await fetch(RFB_URL, { method: "HEAD", cache: "no-store" });
      if (!head.ok) throw new Error("assets missing");
    } catch {
      setPhase("unavailable");
      return;
    }

    // 2. Get a fresh single-use console ticket.
    let ticket: { wsPath: string; ticketId: string };
    try {
      const res = await fetch(`/api/console/${serverId}`, { cache: "no-store" });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error || "could not obtain a console ticket");
      }
      ticket = await res.json();
    } catch (err) {
      setPhase("error");
      setMessage(err instanceof Error ? err.message : "could not obtain a console ticket");
      return;
    }

    // 3. Load the vendored RFB client and connect to the relay.
    let RFB: any;
    try {
      const mod = await importESM(RFB_URL);
      RFB = mod.default ?? mod.RFB ?? mod;
      if (typeof RFB !== "function") throw new Error("noVNC RFB module malformed");
    } catch {
      setPhase("unavailable");
      return;
    }

    if (!containerRef.current) return;
    setPhase("connecting");

    try {
      const rfb = new RFB(containerRef.current, ticket.wsPath, {
        wsProtocols: ["binary"],
      });
      rfb.scaleViewport = true;
      rfb.clipViewport = false;
      rfb.resizeSession = false;
      rfb.showDotCursor = true;
      rfb.background = "#05060f";

      rfb.addEventListener("connect", () => setPhase("connected"));
      rfb.addEventListener("disconnect", (e: any) => {
        setPhase("error");
        setMessage(
          e?.detail?.clean
            ? "Console session ended."
            : "Console disconnected — the relay or hypervisor may be unreachable."
        );
        rfbRef.current = null;
      });
      rfb.addEventListener("securityfailure", (e: any) => {
        setPhase("error");
        setMessage(`Console authentication failed${e?.detail?.reason ? `: ${e.detail.reason}` : "."}`);
      });

      rfbRef.current = rfb;
    } catch (err) {
      setPhase("error");
      setMessage(err instanceof Error ? err.message : "failed to start the console");
    }
  }, [serverId, cleanup]);

  const disconnect = useCallback(() => {
    cleanup();
    setPhase("idle");
    setMessage(null);
  }, [cleanup]);

  const sendCtrlAltDel = useCallback(() => {
    try {
      rfbRef.current?.sendCtrlAltDel();
    } catch {
      /* ignore */
    }
  }, []);

  const fullscreen = useCallback(() => {
    const el = containerRef.current?.parentElement;
    if (el?.requestFullscreen) void el.requestFullscreen();
  }, []);

  const active = phase === "connecting" || phase === "connected";

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="font-semibold">VNC console</h2>
          <p className="mt-1 text-sm text-slate-400">
            Direct graphical access to your server — useful when SSH or networking is unavailable.
          </p>
        </div>
        <div className="flex items-center gap-2">
          {active && (
            <>
              <button type="button" onClick={sendCtrlAltDel} className="btn-secondary">
                Ctrl+Alt+Del
              </button>
              <button type="button" onClick={fullscreen} className="btn-secondary">
                Fullscreen
              </button>
              <button type="button" onClick={disconnect} className="btn-danger">
                Disconnect
              </button>
            </>
          )}
          {!active && phase !== "unavailable" && (
            <button
              type="button"
              onClick={() => void connect()}
              className="btn-primary"
              disabled={phase === "loading"}
            >
              {phase === "loading" ? "Opening…" : "Open console"}
            </button>
          )}
        </div>
      </div>

      {phase === "unavailable" ? (
        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
          <div className="flex items-start gap-3">
            <svg
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#fbbf24"
              strokeWidth="1.6"
              className="mt-0.5 shrink-0"
            >
              <path d="M12 9v4M12 17h.01" />
              <path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z" />
            </svg>
            <div>
              <h3 className="text-sm font-semibold text-amber-200">Console assets not installed</h3>
              <p className="mt-1 text-sm text-slate-400">
                The noVNC client bundle is missing. An operator can install it by running:
              </p>
              <code className="mt-2 inline-block rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
                scripts/fetch-novnc.sh
              </code>
            </div>
          </div>
        </div>
      ) : (
        <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-[#05060f]">
          <div
            ref={containerRef}
            className="flex min-h-[420px] w-full items-center justify-center"
          >
            {phase === "idle" && (
              <div className="px-6 py-16 text-center">
                <div className="mx-auto mb-4 w-fit rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
                  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.5">
                    <rect x="2" y="4" width="20" height="14" rx="2" />
                    <path d="M8 21h8M12 18v3" />
                    <path d="m7 9 3 2-3 2M13 13h4" />
                  </svg>
                </div>
                <p className="text-sm text-slate-400">
                  The console opens a live graphical session. Click{" "}
                  <span className="font-medium text-slate-200">Open console</span> to connect.
                </p>
              </div>
            )}
            {(phase === "loading" || phase === "connecting") && (
              <div className="flex flex-col items-center gap-3 py-16 text-sm text-slate-400">
                <span className="h-6 w-6 animate-spin rounded-full border-2 border-white/20 border-t-brand-400" />
                {phase === "loading" ? "Requesting a secure ticket…" : "Connecting to the console…"}
              </div>
            )}
            {phase === "error" && (
              <div className="px-6 py-16 text-center">
                <p className="text-sm text-red-300">{message ?? "The console is unavailable."}</p>
                <button type="button" onClick={() => void connect()} className="btn-secondary mt-4">
                  Try again
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      <p className="text-xs text-slate-500">
        Console sessions are authenticated with a single-use ticket that expires in 60 seconds. Your
        keystrokes travel to the server over an encrypted relay — credentials are never exposed to your
        browser.
      </p>
    </div>
  );
}

import { SignJWT, jwtVerify } from "jose";
import { cookies } from "next/headers";
import { cache } from "react";
import { db } from "./db";
import type { User } from "@prisma/client";

const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";

export async function createSession(userId: string) {
  const token = await new SignJWT({ sub: userId })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(secret);
  const jar = await cookies();
  jar.set(COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1",
    maxAge: 60 * 60 * 24 * 7,
    path: "/",
  });
}

export async function destroySession() {
  const jar = await cookies();
  jar.delete(COOKIE);
}

const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;

/** The real signed-in account, ignoring any impersonation. */
export const realUser = cache(async (): Promise<User | null> => {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, secret);
    if (!payload.sub) return null;
    const user = await db.user.findUnique({ where: { id: payload.sub } });
    if (!user || user.suspended) return null;
    return user;
  } catch {
    return null;
  }
});

/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
export const currentUser = cache(async (): Promise<User | null> => {
  const real = await realUser();
  if (!real) return null;
  if (real.role === "ADMIN") {
    const jar = await cookies();
    const imp = jar.get(IMP_COOKIE)?.value;
    if (imp) {
      try {
        const { payload } = await jwtVerify(imp, secret);
        if (payload.adminId === real.id && typeof payload.sub === "string") {
          const target = await db.user.findUnique({ where: { id: payload.sub } });
          if (target) return target;
        }
      } catch {
        /* expired/invalid impersonation — fall through to real user */
      }
    }
  }
  return real;
});

/** Non-null when the current request is an admin impersonating a customer. */
export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") return null;
  const target = await currentUser();
  if (!target || target.id === real.id) return null;
  return { admin: real, target };
});

export async function setImpersonation(targetUserId: string) {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
  const token = await new SignJWT({ sub: targetUserId, adminId: real.id })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("2h")
    .sign(secret);
  const jar = await cookies();
  jar.set(IMP_COOKIE, token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 7200 });
}

export async function clearImpersonation() {
  const jar = await cookies();
  jar.delete(IMP_COOKIE);
}

export async function requireUser(): Promise<User> {
  const user = await currentUser();
  if (!user) throw new Error("UNAUTHORIZED");
  return user;
}

export async function requireAdmin(): Promise<User> {
  const user = await requireUser();
  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
  return user;
}

/**
 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
 * per-area gating lives in lib/rbac.ts (`requireArea`).
 */
export async function requireStaff(): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
    throw new Error("FORBIDDEN");
  }
  return user;
}
