// Thin Anthropic Messages API wrapper for the "Build with Claude AI" feature.
// No SDK / no new deps — plain fetch. Gated everywhere by ANTHROPIC_API_KEY.

const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
const MODEL = "claude-sonnet-5";

export type ClaudeMessage = { role: "user" | "assistant"; content: string };

/** True when the feature is enabled (an API key is configured). */
export function anthropicConfigured(): boolean {
  return Boolean(process.env.ANTHROPIC_API_KEY && process.env.ANTHROPIC_API_KEY.trim());
}

/**
 * Send a chat turn to Claude and return the concatenated text of the reply.
 * Throws when the key is missing or the API returns a non-2xx response.
 */
export async function askClaude(
  messages: ClaudeMessage[],
  system: string,
  opts: { maxTokens?: number; timeoutMs?: number } = {}
): Promise<string> {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error("ANTHROPIC_API_KEY is not set");

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? 60_000);
  let res: Response;
  try {
    res = await fetch(ANTHROPIC_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": key,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: MODEL,
        max_tokens: opts.maxTokens ?? 1024,
        system,
        messages,
      }),
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timer);
  }

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Anthropic API ${res.status}: ${body.slice(0, 500)}`);
  }

  const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
  const text = (data.content ?? [])
    .filter((b) => b.type === "text" && typeof b.text === "string")
    .map((b) => b.text as string)
    .join("")
    .trim();
  return text;
}

// "Build with Claude AI" worker handler.
//
// Agentic loop: given a plain-English goal, repeatedly ask Claude for the NEXT
// single shell command to run on the customer's server, execute it over SSH,
// feed the output back, and stop on "DONE", an error, or a hard step cap.
//
// This handler is wired into worker/index.ts's `handlers` map by the
// orchestrator (see INTEGRATION NEEDED in the final report):
//   import { claudeBuild } from "./claude";
//   CLAUDE_BUILD: claudeBuild,

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";
import { askClaude, anthropicConfigured, type ClaudeMessage } from "../lib/anthropic";
import type { Job } from "@prisma/client";

const execFileAsync = promisify(execFile);

/** Hard cap on the number of command steps for a single build. */
export const CLAUDE_MAX_STEPS = 12;

/** Per-command SSH execution timeout. */
const CMD_TIMEOUT_MS = 120_000;
/** Cap on captured output per command (chars) to keep the log bounded. */
const MAX_OUTPUT_CHARS = 4000;
/** Cap on total stored log size. */
const MAX_LOG_CHARS = 60_000;

const SYSTEM_PROMPT = `You are an expert Linux server administrator operating a single Debian/Ubuntu server over SSH as root, on behalf of its owner. You are given a goal and, on each turn, the transcript of commands already run and their output.

Respond with EXACTLY ONE next step and NOTHING else:
- Either a single, non-interactive shell command to run next (one line, no markdown, no backticks, no explanation), or
- The literal word DONE when the goal is fully achieved.

Rules:
- Operate ONLY on this server. Never touch other hosts, networks, or cloud APIs.
- Commands must be non-interactive: use flags like -y / DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
- Keep each command self-contained and idempotent where possible.
- NEVER run destructive whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff, no user/password changes, no disabling SSH.
- Prefer standard packages and system services (apt, systemctl, nginx, ufw, etc.).
- If a previous command failed, adapt; do not blindly repeat it.
- When everything the goal asks for is installed and configured, reply DONE.`;

/** Escape a string for safe single-quoted inclusion in a bash -c argument. */
function shSingleQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

/** Reject obviously catastrophic commands as a defense-in-depth backstop. */
function isForbidden(cmd: string): boolean {
  const c = cmd.toLowerCase();
  const patterns = [
    /rm\s+(-[a-z]*\s+)*(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r)\s+\/(\s|$)/, // rm -rf /
    /\bmkfs\b/,
    /\bfdisk\b/,
    /\bdd\b[^|]*of=\/dev\//,
    /\b(reboot|shutdown|poweroff|halt|init\s+0|init\s+6)\b/,
    /\bshred\b/,
    /:\(\)\s*\{.*\};:/, // fork bomb
    />\s*\/dev\/sd[a-z]/,
  ];
  return patterns.some((p) => p.test(c));
}

/** Run one command on the server over SSH via sshpass. Never throws. */
async function sshExec(
  server: { ipAddress: string | null; rootPassword: string | null; sshPort: number | null },
  command: string
): Promise<{ output: string; failed: boolean }> {
  if (!server.ipAddress || !server.rootPassword) {
    return { output: "[nxeon] server has no reachable IP or root password", failed: true };
  }
  // The worker reaches VMs directly on the private bridge (10.20.0.0/24), so we
  // connect to the private IP on port 22, not the public NAT port.
  const args = [
    "-p",
    server.rootPassword,
    "ssh",
    "-o",
    "StrictHostKeyChecking=no",
    "-o",
    "UserKnownHostsFile=/dev/null",
    "-o",
    "ConnectTimeout=10",
    "-o",
    "BatchMode=no",
    `root@${server.ipAddress}`,
    // Wrap in bash -c with a single-quoted payload so complex commands survive intact.
    `bash -c ${shSingleQuote(command)}`,
  ];
  try {
    const { stdout, stderr } = await execFileAsync("sshpass", args, {
      timeout: CMD_TIMEOUT_MS,
      maxBuffer: 8 * 1024 * 1024,
      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
    });
    const out = `${stdout}${stderr ? `\n${stderr}` : ""}`.trim();
    return { output: out || "[no output]", failed: false };
  } catch (e: any) {
    // execFile rejects on non-zero exit or timeout; capture whatever we got.
    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
    const reason = e?.killed
      ? `[nxeon] command timed out after ${CMD_TIMEOUT_MS / 1000}s`
      : `[nxeon] command exited with code ${e?.code ?? "?"}`;
    return { output: `${out ? out + "\n" : ""}${reason}`, failed: true };
  }
}

function truncate(s: string, max: number): string {
  return s.length > max ? s.slice(0, max) + "\n…[truncated]" : s;
}

export async function claudeBuild(job: Job): Promise<void> {
  const payload = (job.payload ?? {}) as { buildId?: string };
  const buildId = payload.buildId;
  if (!buildId) throw new Error("claudeBuild: missing buildId in job payload");

  const build = await db.claudeBuild.findUnique({ where: { id: buildId }, include: { server: true } });
  if (!build) throw new Error(`claudeBuild: build ${buildId} not found`);
  const server = build.server;

  // Refuse to run if the feature is not enabled.
  if (!anthropicConfigured()) {
    await db.claudeBuild.update({
      where: { id: buildId },
      data: { status: "FAILED", log: (build.log ?? "") + "\n[nxeon] Build with Claude is not enabled (no API key).\n" },
    });
    return;
  }

  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "RUNNING" } });

  let log = build.log ?? "";
  const append = async (chunk: string, steps: number) => {
    log = truncate(log + chunk, MAX_LOG_CHARS);
    await db.claudeBuild.update({ where: { id: buildId }, data: { log, steps } });
  };

  await append(`# Goal: ${build.prompt}\n\n`, 0);

  // Conversation history handed to Claude. The goal lives in the first user turn.
  const messages: ClaudeMessage[] = [
    { role: "user", content: `Goal: ${build.prompt}\n\nProvide the first command, or DONE if nothing is needed.` },
  ];

  let steps = 0;
  let finalStatus: "DONE" | "FAILED" = "DONE";

  try {
    while (steps < CLAUDE_MAX_STEPS) {
      let reply: string;
      try {
        reply = await askClaude(messages, SYSTEM_PROMPT, { maxTokens: 512, timeoutMs: 60_000 });
      } catch (e: any) {
        await append(`\n[nxeon] Claude request failed: ${e?.message ?? e}\n`, steps);
        finalStatus = "FAILED";
        break;
      }

      // Normalize the model's reply into a single command line.
      const command = reply.replace(/^```[a-z]*\n?|\n?```$/g, "").trim();

      if (!command || /^done\b/i.test(command)) {
        await append(`\n[nxeon] Claude reports the goal is complete.\n`, steps);
        finalStatus = "DONE";
        break;
      }

      messages.push({ role: "assistant", content: command });

      if (isForbidden(command)) {
        const note = `[nxeon] Refused unsafe command: ${command}`;
        await append(`\n$ ${command}\n${note}\n`, steps);
        // Tell Claude why and let it adapt.
        messages.push({ role: "user", content: `That command was refused by the safety filter as potentially destructive. Provide a safer next command, or DONE.` });
        continue;
      }

      steps += 1;
      const { output, failed } = await sshExec(server, command);
      const shown = truncate(output, MAX_OUTPUT_CHARS);
      await append(`\n$ ${command}\n${shown}\n`, steps);

      messages.push({
        role: "user",
        content: `Output of the last command${failed ? " (it FAILED)" : ""}:\n${shown}\n\nProvide the next command, or DONE if the goal is complete.`,
      });
    }

    if (steps >= CLAUDE_MAX_STEPS && finalStatus !== "FAILED") {
      await append(`\n[nxeon] Reached the ${CLAUDE_MAX_STEPS}-step limit — stopping.\n`, steps);
    }
  } catch (e: any) {
    await append(`\n[nxeon] Build error: ${e?.message ?? e}\n`, steps);
    finalStatus = "FAILED";
  }

  await db.claudeBuild.update({ where: { id: buildId }, data: { status: finalStatus, steps } });

  try {
    await db.notification.create({
      data: {
        userId: build.userId,
        title: finalStatus === "DONE" ? `Claude finished building on ${server.hostname}` : `Claude build failed on ${server.hostname}`,
        body: build.prompt.slice(0, 140),
        href: `/dashboard/build`,
      },
    });
  } catch {
    /* notification is best-effort */
  }
}

"use server";

// Server actions for the "Build with Claude AI" feature.
// Only async functions are exported (Next.js "use server" constraint).

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { anthropicConfigured } from "./anthropic";

const MAX_PROMPT_CHARS = 2000;
const MIN_PROMPT_CHARS = 8;
// Cap how many builds a user may have in flight, and how many they can start in
// a short window, to keep API + SSH usage sane.
const MAX_ACTIVE_BUILDS_PER_USER = 3;
const RATE_WINDOW_MS = 60_000;
const MAX_BUILDS_PER_WINDOW = 5;

export async function submitBuild(
  serverId: string,
  prompt: string
): Promise<{ error?: string; buildId?: string }> {
  const user = await requireUser();

  if (!anthropicConfigured()) {
    return { error: "Build with Claude is not enabled yet — ask an admin to add an API key." };
  }

  const clean = (prompt ?? "").trim();
  if (clean.length < MIN_PROMPT_CHARS) {
    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
  }
  if (clean.length > MAX_PROMPT_CHARS) {
    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
  }

  // Ownership: the server must belong to this user.
  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
  if (!server) return { error: "Server not found." };
  if (server.status !== "RUNNING") {
    return { error: "The server must be running to build on it." };
  }
  if (!server.ipAddress || !server.rootPassword) {
    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
  }

  // Rate sanity.
  const active = await db.claudeBuild.count({
    where: { userId: user.id, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (active >= MAX_ACTIVE_BUILDS_PER_USER) {
    return { error: "You already have builds running. Wait for them to finish before starting another." };
  }
  const recent = await db.claudeBuild.count({
    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
  });
  if (recent >= MAX_BUILDS_PER_WINDOW) {
    return { error: "Too many builds started just now — please wait a minute and try again." };
  }
  // One in-flight build per server keeps the SSH session serialized.
  const serverBusy = await db.claudeBuild.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (serverBusy > 0) {
    return { error: "A build is already running on this server." };
  }

  const build = await db.claudeBuild.create({
    data: { userId: user.id, serverId, prompt: clean, status: "QUEUED" },
  });

  // Enqueue the worker job; the handler reads the build via payload.buildId.
  await db.job.create({
    data: { type: "CLAUDE_BUILD", serverId, payload: { buildId: build.id } },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "server.claude_build", detail: `${serverId} ${build.id}` },
  }).catch(() => {});

  revalidatePath("/dashboard/build");
  return { buildId: build.id };
}

export async function listBuilds(serverId?: string) {
  const user = await requireUser();
  return db.claudeBuild.findMany({
    where: { userId: user.id, ...(serverId ? { serverId } : {}) },
    orderBy: { createdAt: "desc" },
    take: 20,
    include: { server: { select: { hostname: true } } },
  });
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";

export const dynamic = "force-dynamic";

/**
 * GET /api/claude/[id]
 * Ownership-checked live status for a ClaudeBuild — polled by the client log viewer.
 * Returns { status, steps, log }.
 */
export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const build = await db.claudeBuild.findUnique({
    where: { id },
    select: { userId: true, status: true, steps: true, log: true },
  });
  if (!build || (build.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  return NextResponse.json(
    { status: build.status, steps: build.steps, log: build.log },
    { headers: { "cache-control": "no-store" } }
  );
}

"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { submitBuild } from "@/lib/actions-claude";

type ServerOption = { id: string; hostname: string };
type BuildState = { status: string; steps: number; log: string };

const EXAMPLES = [
  "Install and configure nginx serving a simple landing page over HTTP.",
  "Set up Node.js LTS, PM2, and a UFW firewall allowing only SSH and HTTP/HTTPS.",
  "Install Docker and run a Postgres 16 container with a persistent volume.",
];

const TERMINAL = new Set(["DONE", "FAILED"]);

export function ClaudeBuilder({ servers }: { servers: ServerOption[] }) {
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  const [prompt, setPrompt] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [buildId, setBuildId] = useState<string | null>(null);
  const [state, setState] = useState<BuildState | null>(null);
  const [pending, startTransition] = useTransition();
  const logRef = useRef<HTMLPreElement>(null);

  // Poll the build status while a build is active.
  useEffect(() => {
    if (!buildId) return;
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;

    const tick = async () => {
      try {
        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
        if (res.ok) {
          const data = (await res.json()) as BuildState;
          if (alive) setState(data);
          if (data.status && TERMINAL.has(data.status)) return; // stop polling
        }
      } catch {
        /* transient — keep polling */
      }
      if (alive) timer = setTimeout(tick, 2000);
    };
    void tick();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [buildId]);

  // Keep the log scrolled to the bottom as it streams.
  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [state?.log]);

  const running = Boolean(buildId) && !(state && TERMINAL.has(state.status));

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    startTransition(async () => {
      const res = await submitBuild(serverId, prompt);
      if (res.error) {
        setError(res.error);
        return;
      }
      if (res.buildId) {
        setBuildId(res.buildId);
        setState({ status: "QUEUED", steps: 0, log: "" });
      }
    });
  };

  const reset = () => {
    setBuildId(null);
    setState(null);
    setPrompt("");
    setError(null);
  };

  const statusTone =
    state?.status === "DONE"
      ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300"
      : state?.status === "FAILED"
      ? "border-red-500/40 bg-red-500/10 text-red-300"
      : "border-amber-500/40 bg-amber-500/10 text-amber-300";

  return (
    <div className="space-y-6">
      <form onSubmit={onSubmit} className="card space-y-4 p-5">
        <div>
          <label className="mb-1.5 block text-sm font-medium text-slate-300">Server</label>
          <select
            className="input"
            value={serverId}
            onChange={(e) => setServerId(e.target.value)}
            disabled={running || pending}
          >
            {servers.map((s) => (
              <option key={s.id} value={s.id}>
                {s.hostname}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="mb-1.5 block text-sm font-medium text-slate-300">
            What should Claude build?
          </label>
          <textarea
            className="input min-h-[110px] resize-y font-normal"
            placeholder="e.g. Install and configure a Node.js app served behind nginx with a firewall."
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            maxLength={2000}
            disabled={running || pending}
          />
          <div className="mt-2 flex flex-wrap gap-2">
            {EXAMPLES.map((ex) => (
              <button
                key={ex}
                type="button"
                onClick={() => setPrompt(ex)}
                disabled={running || pending}
                className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-400 hover:text-slate-200 disabled:opacity-50"
              >
                {ex.length > 46 ? ex.slice(0, 46) + "…" : ex}
              </button>
            ))}
          </div>
        </div>

        {error && <p className="text-sm text-red-300">{error}</p>}

        <div className="flex items-center gap-3">
          <button
            type="submit"
            className="btn-primary"
            disabled={running || pending || !serverId || prompt.trim().length < 8}
          >
            {pending ? "Starting…" : running ? "Building…" : "Build with Claude"}
          </button>
          {buildId && !running && (
            <button type="button" onClick={reset} className="btn-secondary">
              New build
            </button>
          )}
        </div>
        <p className="text-xs text-slate-500">
          Claude runs up to 12 shell commands over SSH on the selected server, then stops. Review the
          log below — you are responsible for changes made to your server.
        </p>
      </form>

      {state && (
        <div className="card space-y-3 p-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <span className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${statusTone}`}>
                {running && (
                  <span className="mr-2 h-1.5 w-1.5 animate-pulse rounded-full bg-current" />
                )}
                {state.status.toLowerCase()}
              </span>
              <span className="text-xs text-slate-500">
                step {state.steps} / 12
              </span>
            </div>
          </div>
          <pre
            ref={logRef}
            className="max-h-[440px] overflow-auto whitespace-pre-wrap break-words rounded-xl border border-white/[0.08] bg-navy-950/80 p-4 font-mono text-xs leading-relaxed text-slate-300"
          >
            {state.log || (running ? "Waiting for the worker to pick up the job…" : "No output.")}
          </pre>
        </div>
      )}
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { anthropicConfigured } from "@/lib/anthropic";
import { PageHeader, EmptyState, StatusDot, timeAgo } from "@/components/ui/primitives";
import { ClaudeBuilder } from "@/components/customer/ClaudeBuilder";

export const dynamic = "force-dynamic";

export default async function BuildPage() {
  const user = await requireUser();
  const enabled = anthropicConfigured();

  const [servers, builds] = await Promise.all([
    db.server.findMany({
      where: { userId: user.id, status: "RUNNING" },
      select: { id: true, hostname: true },
      orderBy: { createdAt: "desc" },
    }),
    db.claudeBuild.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 15,
      include: { server: { select: { hostname: true } } },
    }),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Build with Claude AI"
        sub="Describe what you want in plain English — Claude configures your server for you."
      />

      {!enabled ? (
        <div className="card border-amber-500/30 bg-amber-500/[0.06] p-6">
          <h3 className="text-sm font-semibold text-amber-200">Not enabled yet</h3>
          <p className="mt-1 max-w-xl text-sm text-slate-400">
            The AI builder isn&apos;t turned on for this platform. Ask an admin to add an Anthropic
            API key (<code className="rounded bg-navy-950/80 px-1.5 py-0.5 font-mono text-xs">ANTHROPIC_API_KEY</code>)
            to enable it.
          </p>
        </div>
      ) : servers.length === 0 ? (
        <EmptyState
          title="No running servers"
          sub="Claude builds on a running server. Start or deploy one, then come back here."
          action={
            <Link href="/dashboard/servers" className="btn-primary">
              Go to servers
            </Link>
          }
        />
      ) : (
        <ClaudeBuilder servers={servers} />
      )}

      {builds.length > 0 && (
        <div className="space-y-3">
          <h2 className="text-sm font-semibold text-slate-300">Recent builds</h2>
          <div className="table-shell">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
                  <th className="px-4 py-3 font-medium">Prompt</th>
                  <th className="px-4 py-3 font-medium">Server</th>
                  <th className="px-4 py-3 font-medium">Status</th>
                  <th className="px-4 py-3 font-medium">Steps</th>
                  <th className="px-4 py-3 font-medium">When</th>
                </tr>
              </thead>
              <tbody>
                {builds.map((b) => (
                  <tr key={b.id} className="border-t border-white/[0.06]">
                    <td className="max-w-xs truncate px-4 py-3 text-slate-300" title={b.prompt}>
                      {b.prompt}
                    </td>
                    <td className="px-4 py-3 text-slate-400">{b.server.hostname}</td>
                    <td className="px-4 py-3">
                      <StatusDot status={b.status} />
                    </td>
                    <td className="px-4 py-3 text-slate-400">{b.steps}</td>
                    <td className="px-4 py-3 text-slate-500">{timeAgo(b.createdAt)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
